import torch,torch.nn as nn; exec("class KVCache:\n    def __init__(self):\n        self.cache_k = None\n        self.cache_v = None\n    def update(self, new_k, new_v):\n        if self.cache_k is None:\n            self.cache_k = new_k\n            self.cache_v = new_v\n        else:\n            self.cache_k = torch.cat([self.cache_k, new_k], dim=1)\n            self.cache_v = torch.cat([self.cache_v, new_v], dim=1)\n        return self.cache_k, self.cache_v\n    def clear(self):\n        self.cache_k = None\n        self.cache_v = None\nclass CachedAttention(nn.Module):\n    def __init__(self, model_dim):\n        super().__init__()\n        torch.manual_seed(0)\n        self.q_proj = nn.Linear(model_dim, model_dim, bias=False)\n        self.k_proj = nn.Linear(model_dim, model_dim, bias=False)\n        self.v_proj = nn.Linear(model_dim, model_dim, bias=False)\n    def forward(self, x, kv_cache=None):\n        q = self.q_proj(x)\n        k = self.k_proj(x)\n        v = self.v_proj(x)\n        if kv_cache is None:\n            kv_cache = KVCache()\n        full_k, full_v = kv_cache.update(k, v)\n        scores = (q @ full_k.transpose(-2, -1)) * (full_k.shape[-1] ** -0.5)\n        T_q = q.shape[1]\n        T_k = full_k.shape[1]\n        mask = torch.triu(torch.ones(T_q, T_k), diagonal=T_k - T_q + 1).bool()\n        scores = scores.masked_fill(mask, float('-inf'))\n        weights = torch.softmax(scores, dim=-1)\n        output = weights @ full_v\n        return torch.round(output, decimals=4), kv_cache")